contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(address recipient) public payable {
        // no precondition: any recipient address is valid, including zero and this contract
        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // On a successful call, withdrawReward sends 0 wei (no prior rewards), so
            // c's balance must not decrease. Also the bonus should be marked claimed.
            assert(address(c).balance >= beforeBalance);
        } else {
            // The call reverted: state must be unchanged as observed by c's balance.
            assert(address(c).balance == beforeBalance);
        }
    }
}

