contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address recipient) public payable {
        require(recipient != address(0));
        require(address(c).balance >= 100);

        // Precondition: recipient has NOT already claimed the bonus.
        // This is guaranteed by a fresh deployment, but we must not call
        // getFirstWithdrawalBonus before this call in this single run, so
        // the deciding call is the first one for `recipient`.

        uint contractBefore = address(c).balance;
        uint recipientBefore = recipient.balance;

        bool reverted;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: since recipient had not claimed the bonus before this
        // call, the call must not revert because of the claim flag. It succeeds
        // unless the recipient's fallback rejects the 100 wei transfer.
        // We observe that after a successful call, c's balance decreased by 100
        // and recipient's balance did not decrease.
        // If the call reverted, it must be because the recipient rejected the
        // transfer (success = false), not because of the claim flag.
        assert(reverted || (address(c).balance == contractBefore - 100 && recipient.balance >= recipientBefore));
    }

    receive() external payable {}
}

