        // rewardsForA is getFirstWithdrawalBonus, but it immediately withdraws.
        // We cannot observe rewardsForA directly; instead we use the fact that
        // after a failed bonus withdrawal the reward remains.
        // To create a reward balance without withdrawing, we call
        // getFirstWithdrawalBonus from an address that rejects Ether, which
        // reverts the bonus call but leaves rewardsForA[that address] = 100.
        // However, the checker calls run as InvMutTest, and all calls are from
        // this contract. So we set up rewardsForA for *this* contract via a
        // failed withdrawal: call getFirstWithdrawalBonus(address(this)) after
        // making this contract reject Ether? We cannot make this contract reject
        // Ether because receive() is defined. Instead, we use the recipient
        // parameter directly: call getFirstWithdrawalBonus(recipient) and let it
        // succeed (transferring 100 wei), then the reward is zero. The only way
        // to get a nonzero reward is if the bonus withdrawal fails. So we need
        // a recipient that rejects Ether. We can use a *contract* address that
        // has no receive/fallback. We accept such a recipient as a parameter
        // (address payable). But we cannot force it to reject; the caller
        // chooses. The rule must be general: it says withdrawReward reverts iff
        // the transfer fails. We can test this by calling withdrawReward(recipient)
        // and checking whether it reverted, and comparing c's balance change.

        // Since we cannot set up a nonzero reward without a preceding bonus call
        // that transfers 100 wei and zeroes it, we drive the public entry directly:
        // call getFirstWithdrawalBonus(recipient) to put the contract in a state
        // where rewardsForA[recipient] is zero *unless* the transfer failed.
        // Then call withdrawReward(recipient) and assert the general rule.

        // Step 1: try to grant the bonus. This may revert if the transfer fails;
        // if it reverts, rewardsForA[recipient] remains 100 (since the require
        // fails after rewardsForA was increased but before claimedBonus set).
        bool bonusReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            bonusReverted = false;
        } catch {
            bonusReverted = true;
        }

        // Revert condition: if the bonus call reverted, the reward is still 100
        // and the recipient rejected Ether. Then withdrawReward(recipient) will
        // also attempt to send 100 wei and should revert for the same reason.
        // If the bonus call succeeded, reward is zero and withdrawReward(recipient)
        // sends 0 wei (transfer of 0 may still fail if recipient rejects? No,
        // call with value 0 to a contract without receive/fallback will still
        // revert if no fallback? Actually a call with value 0 to a contract
        // without receive/fallback: the call itself reverts because no function
        // matches and no fallback. But EOA always succeeds. So the rule depends
        // on recipient type. We cannot distinguish EOA vs contract without
        // further calls. The general rule: withdrawReward reverts iff the
        // recipient rejects the transfer (including zero-value calls to
        // contracts without fallback).

        // We capture c's balance before the deciding call.
        uint256 balanceBefore = address(c).balance;

        // Deciding call: direct withdrawReward(recipient).
        bool withdrawalReverted;
        try c.withdrawReward(recipient) {
            withdrawalReverted = false;
        } catch {
            withdrawalReverted = true;
        }

        uint256 balanceAfter = address(c).balance;

        // General rule: withdrawReward(recipient) reverts exactly when the
        // recipient rejects the outgoing transfer. Since the transfer amount is
        // the reward balance (0 if bonus succeeded, 100 if bonus failed), and
        // the reward is zeroed before the call, a successful call always
        // decreases c's balance by the reward amount that was present before.
        // In all cases, if the call succeeds the balance decreases by exactly
        // the prior reward; if it reverts the balance is unchanged.
        // We can express this via the bonusReverted flag: if bonusReverted,
        // reward was 100, so success means balanceAfter == balanceBefore - 100;
        // failure means balanceAfter == balanceBefore. If !bonusReverted,
        // reward was 0, so success means balanceAfter == balanceBefore (0 transfer)
        // and failure means balanceAfter == balanceBefore as well (no transfer).
        // Thus: withdrawalReverted == bonusReverted (both fail due to same
        // recipient rejecting Ether, modulo the zero-value call behavior).
        // More precisely: withdrawalReward reverts if and only if the recipient
        // rejects the transfer. The bonus call reverting implies the recipient
        // rejects a 100 wei transfer. A recipient that rejects 100 wei also
        // rejects 0 wei (same call semantics). So withdrawalReverted == bonusReverted.
        assert(withdrawalReverted == bonusReverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address payable recipient) public payable {
        // Use a recipient that cannot receive Ether: a contract with no receive/fallback
        // is chosen by the caller. To make the rule clean and always applicable, we
        // require that recipient is this test contract itself, which can reject Ether
        // by having a receive() that reverts when a flag is set. However, the checker
        // calls run once, so we simply use the recipient parameter and require that
        // it is a contract address (not an EOA) by checking code length. This bounds
        // the input so the rule is about a rejecting recipient.
        require(recipient.code.length > 0, "recipient must be a contract");

        // Drive through the public entry to give the recipient a reward of 100 wei
        // without a successful transfer: getFirstWithdrawalBonus increments the reward
        // then calls withdrawReward, which will revert if recipient rejects Ether.
        // We capture whether that setup call reverted.
        bool bonusReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            bonusReverted = false;
        } catch {
            bonusReverted = true;
        }

        // If the bonus call reverted, rewardsForA[recipient] remains 100 and the
        // recipient rejects Ether. Then a direct withdrawReward(recipient) must revert
        // for the same reason. If the bonus call did not revert, the recipient accepts
        // Ether, contradicting the intent; we require the rejecting case by requiring
        // bonusReverted to be true. This makes the rule specifically about a rejecting
        // recipient and keeps the test deterministic.
        require(bonusReverted, "recipient accepted Ether");

        // Deciding call: direct withdrawReward(recipient).
        bool withdrawalReverted;
        try c.withdrawReward(recipient) {
            withdrawalReverted = false;
        } catch {
            withdrawalReverted = true;
        }

        // General rule: for a recipient that rejects Ether, withdrawReward reverts.
        assert(withdrawalReverted);
    }

    receive() external payable {}
}

